package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.AuthDtos.*;import com.example.riskplatform.service.AuthService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController{private final AuthService s;@PostMapping("/login")public ApiResponse<LoginResponse>login(@Valid @RequestBody LoginRequest r){return ApiResponse.ok(s.login(r));}}